VALUES('BScN','Paper I','Medical-Surgical Nursing','Professional Practice','What is the primary goal of the nursing process in patient care?','Administering medications','Monitoring vital signs','Providing emotional support','Promoting patient well-being through systematic assessment, planning, intervention and evaluation','D','ADPIE is cyclical and iterative; BScN nurses apply critical thinking at each step, formulate NANDA nursing diagnoses, set SMART outcomes and evaluate goal achievement using evidence-based interventions (nursing process texts; Brunner & Suddarth).','easy',NULL,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Patient confidentiality — ethical principle in nursing ───────────────────
-- Per §12: Paper II for both (professional ethics)
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Health Systems & Management','Professional Ethics','Which of the following is an example of an ethical principle in nursing practice?','Administering medications as ordered by the physician','Ensuring patient confidentiality','Monitoring vital signs regularly','Adhering to strict time management','B','Ensuring patient confidentiality is an ethical principle (privacy/autonomy) grounded in the NCK Code of Conduct; it requires nurses to protect patient information from unauthorised disclosure (NCK Scope of Practice; Kenya Data Protection Act; nursing ethics).','easy',NULL,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Nursing Management & Leadership','Professional Ethics','Which of the following is an example of an ethical principle in nursing practice?','Administering medications as ordered by the physician','Ensuring patient confidentiality','Monitoring vital signs regularly','Adhering to strict time management','B','Confidentiality is a sub-principle of autonomy; BScN nurses apply it in electronic health records, social media use and multidisciplinary communications — disclosing only on a need-to-know basis within the care team (NCK Code of Conduct; Kenya Data Protection Act 2019).','easy',NULL,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

