-- ── Pressure ulcer prevention — repositioning ────────────────────────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Medical-Surgical Nursing','Wound Care','Which of the following is a nursing intervention for preventing pressure ulcers?','Administering pain medication','Monitoring blood pressure','Turning and repositioning the patient regularly','Providing emotional support','C','Regular 2-hourly turning and repositioning relieves sustained pressure over bony prominences, restoring blood flow and preventing ischaemic tissue damage leading to pressure ulcers (Brunner & Suddarth; NPUAP/EPUAP pressure ulcer prevention guidelines).','easy',NULL,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Medical-Surgical Nursing','Wound Care','Which of the following is a nursing intervention for preventing pressure ulcers?','Administering pain medication','Monitoring blood pressure','Turning and repositioning the patient regularly','Providing emotional support','C','2-hourly repositioning is the cornerstone; supplement with pressure-redistributing surfaces, skin inspection, moisture management and nutritional optimisation. BScN nurses lead pressure ulcer prevention programmes and conduct RCAs for hospital-acquired pressure injuries (Brunner & Suddarth; NPUAP/EPUAP guidelines).','easy',NULL,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

