INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Surgical Nursing','Post-operative Care','What is the primary goal of nursing care in the immediate post-anaesthesia care unit (PACU)?','To discharge the patient home as quickly as possible','To administer pain medication on schedule','To monitor and stabilise the patient''s vital signs and recovery from anaesthesia','To complete paperwork','C','In the PACU the priority is monitoring and stabilising vital signs, airway, oxygenation, consciousness level and haemodynamic status while the patient recovers from anaesthesia before transfer to the ward (Brunner & Suddarth; perioperative nursing).','easy',NULL,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Surgical Nursing','Post-operative Care','What is the primary goal of nursing care in the immediate post-anaesthesia care unit (PACU)?','To discharge the patient home as quickly as possible','To administer pain medication on schedule','To monitor and stabilise the patient''s vital signs and recovery from anaesthesia','To complete paperwork','C','PACU Aldrete scoring guides discharge readiness: O2 sat, activity, circulation, consciousness, colour. BScN nurses recognise PACU emergencies (airway obstruction, laryngospasm, malignant hyperthermia) and intervene promptly (Brunner & Suddarth; PACU nursing standards).','easy',NULL,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

